// Shobu boss 'alphabeta' -- generated by tools/bundle_boss.py from lab/shobu.hpp, lab/bosses.hpp, lab/boss_main.cpp
#define BOSS_NAME "alphabeta"
#define BOSS_MOVE(p, rng) ([&] { AlphaBeta a(rng()); a.quiesce = AB_QUIESCE; return a.search(p, AB_DEPTH, 0.060); }())
#define BOSS_SEED ((uint64_t)std::chrono::steady_clock::now().time_since_epoch().count())
#define AB_DEPTH 3
#define AB_QUIESCE 0
// Shobu engine for analysis (not a submission). Cell = 16*board + 4*row + col.
// Boards: 0 = black home dark, 1 = black home light, 2 = white home dark, 3 = white home light
// (colour = board & 1). Black (side 0) starts on row 0 of every board, white (side 1) on row 3.
// A move = passive (home board, path must be empty) + aggressive (a board of the other colour,
// same direction and distance, may push exactly one enemy stone; pushed off the board = removed).
// Win: remove every enemy stone from one board. No legal move = loss.
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

namespace shobu {

static const int DR[8] = {1, 1, 0, -1, -1, -1, 0, 1};
static const int DC[8] = {0, 1, 1, 1, 0, -1, -1, -1};

struct Tables {
    int8_t nb[64][8][4];  // nb[cell][dir][dist] (dist 1..3), -1 = off the board
    Tables() {
        for (int i = 0; i < 64; i++)
            for (int d = 0; d < 8; d++)
                for (int k = 0; k < 4; k++) {
                    int b = i >> 4, r = (i >> 2) & 3, c = i & 3;
                    int rr = r + DR[d] * k, cc = c + DC[d] * k;
                    nb[i][d][k] = (rr < 0 || rr > 3 || cc < 0 || cc > 3) ? -1 : int8_t(16 * b + 4 * rr + cc);
                }
    }
};
inline const Tables T;

struct Move {
    uint8_t p, a, d, k;  // passive stone, aggressive stone, direction, distance
};

struct Pos {
    uint64_t s[2];
    int stm = 0;
    static Pos start() {
        Pos q;
        q.s[0] = q.s[1] = 0;
        for (int b = 0; b < 4; b++)
            for (int c = 0; c < 4; c++) {
                q.s[0] |= 1ull << (16 * b + c);
                q.s[1] |= 1ull << (16 * b + 12 + c);
            }
        q.stm = 0;
        return q;
    }
    uint64_t occ() const { return s[0] | s[1]; }

    // Appends all legal moves.
    void gen(std::vector<Move>& out) const {
        out.clear();
        const uint64_t me = s[stm], op = s[stm ^ 1], oc = me | op;
        for (int h = 2 * stm; h < 2 * stm + 2; h++) {
            uint64_t ps = me & (0xFFFFull << (16 * h));
            while (ps) {
                int p = __builtin_ctzll(ps);
                ps &= ps - 1;
                for (int d = 0; d < 8; d++) {
                    for (int k = 1; k <= 2; k++) {
                        int t = T.nb[p][d][k];
                        if (t < 0 || (oc >> t & 1)) break;  // blocked: dist 2 also impossible
                        // aggressive boards: colour != colour(h)
                        for (int a = (h & 1) ^ 1; a < 4; a += 2) {
                            uint64_t as = me & (0xFFFFull << (16 * a));
                            while (as) {
                                int x = __builtin_ctzll(as);
                                as &= as - 1;
                                if (aggrOk(x, d, k, me, op)) out.push_back({uint8_t(p), uint8_t(x), uint8_t(d), uint8_t(k)});
                            }
                        }
                    }
                }
            }
        }
    }

    static bool aggrOk(int x, int d, int k, uint64_t me, uint64_t op) {
        int land = T.nb[x][d][k];
        if (land < 0) return false;
        int n = 0;
        for (int j = 1; j <= k; j++) {
            int c = T.nb[x][d][j];
            if (me >> c & 1) return false;
            if (op >> c & 1) n++;
        }
        if (n == 0) return true;
        if (n > 1) return false;
        int beyond = T.nb[x][d][k + 1];
        return beyond < 0 || !(((me | op) >> beyond) & 1);
    }

    // Plays m; returns true if the mover won (an enemy board emptied).
    bool play(const Move& m) {
        uint64_t& me = s[stm];
        uint64_t& op = s[stm ^ 1];
        me ^= (1ull << m.p) | (1ull << T.nb[m.p][m.d][m.k]);
        for (int j = 1; j <= m.k; j++) {
            int c = T.nb[m.a][m.d][j];
            if (op >> c & 1) {
                op ^= 1ull << c;
                int beyond = T.nb[m.a][m.d][m.k + 1];
                if (beyond >= 0) op |= 1ull << beyond;
                break;
            }
        }
        me ^= (1ull << m.a) | (1ull << T.nb[m.a][m.d][m.k]);
        int b = m.a >> 4;
        bool win = ((op >> (16 * b)) & 0xFFFF) == 0;
        stm ^= 1;
        return win;
    }

    std::string str() const {
        // two rows of boards: white home (2,3) on top, black home (0,1) below; row 3 printed first
        std::string o;
        for (int top = 1; top >= 0; top--) {
            for (int r = 3; r >= 0; r--) {
                for (int bb = 0; bb < 2; bb++) {
                    int b = 2 * top + bb;
                    for (int c = 0; c < 4; c++) {
                        int i = 16 * b + 4 * r + c;
                        o += (s[0] >> i & 1) ? 'x' : (s[1] >> i & 1) ? 'o' : '.';
                    }
                    o += bb ? "\n" : "  ";
                }
            }
            o += "\n";
        }
        return o;
    }
};

inline bool sameMove(const Move& a, const Move& b) { return a.p == b.p && a.a == b.a && a.d == b.d && a.k == b.k; }

}  // namespace shobu
// Boss algorithms, shared by the lab (lab.cpp) and the standalone boss files (bundled by
// tools/bundle_boss.py), so what the lab measures is what the league ships.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <random>
#include <vector>

namespace shobu {

// Material from the side to move's point of view: losing the last stones of a board hurts most.
inline int material(const Pos& p) {
    static const int W[5] = {0, 0, 100, 150, 180};
    int v = 0;
    for (int b = 0; b < 4; b++) {
        v += W[__builtin_popcountll((p.s[p.stm] >> (16 * b)) & 0xFFFF)];
        v -= W[__builtin_popcountll((p.s[p.stm ^ 1] >> (16 * b)) & 0xFFFF)];
    }
    return v;
}

// Exactly the legal moves (as Pos::gen) whose aggressive move pushes an enemy stone off its board,
// without generating the rest: quiescence searches only these, and most of its nodes have none.
inline void genPushOffs(const Pos& p, std::vector<Move>& out) {
    out.clear();
    const uint64_t me = p.s[p.stm], op = p.s[p.stm ^ 1], oc = me | op;
    for (int a = 0; a < 4; a++) {
        uint64_t as = me & (0xFFFFull << (16 * a));
        while (as) {
            int x = __builtin_ctzll(as);
            as &= as - 1;
            for (int d = 0; d < 8; d++)
                for (int k = 1; k <= 2; k++) {
                    if (T.nb[x][d][k] < 0) break;                       // landing off the board
                    if (T.nb[x][d][k + 1] >= 0) continue;               // a pushed stone would stay on
                    bool push = false;
                    for (int j = 1; j <= k; j++) if (op >> T.nb[x][d][j] & 1) push = true;
                    if (!push || !Pos::aggrOk(x, d, k, me, op)) continue;
                    // passive partners: own stones on a home board of the other colour, path empty
                    for (int h = 2 * p.stm; h < 2 * p.stm + 2; h++) {
                        if ((h & 1) == (a & 1)) continue;
                        uint64_t ps = me & (0xFFFFull << (16 * h));
                        while (ps) {
                            int y = __builtin_ctzll(ps);
                            ps &= ps - 1;
                            bool ok = true;
                            for (int j = 1; j <= k && ok; j++) {
                                int t = T.nb[y][d][j];
                                if (t < 0 || (oc >> t & 1)) ok = false;
                            }
                            if (ok) out.push_back({uint8_t(y), uint8_t(x), uint8_t(d), uint8_t(k)});
                        }
                    }
                }
        }
    }
}

// Greedy: a winning move if there is one, else the move leaving the best material, ties at random.
// Looks one ply ahead only: it never sees the opponent's reply.
inline Move greedyMove(const Pos& p, std::mt19937_64& rng) {
    std::vector<Move> ms;
    p.gen(ms);
    int best = -1 << 30, count = 0;
    Move bm = ms[0];
    for (auto& m : ms) {
        Pos q = p;
        if (q.play(m)) return m;
        int v = -material(q);
        if (v > best) { best = v; bm = m; count = 1; }
        else if (v == best && rng() % ++count == 0) bm = m;
    }
    return bm;
}

// UCT with random playouts (a playout reaching `cap` plies is a draw, or decided by material when
// evalAtCap). Options, each measured separately (NOTES): `solver` = MCTS-Solver, proven wins and
// losses propagate up the tree and proven-lost children are never selected; `decisive` = a new node
// scans its moves for an immediate win, so a one-move win is proven on creation.
struct Mcts {
    struct Node {
        Move m;
        int parent, mover, winner = -1;  // winner >= 0: proven (terminal or solved) for that colour
        int visits = 0;
        float wins = 0;                  // from the point of view of `mover`
        std::vector<int> kids;
        std::vector<Move> untried;
    };
    std::vector<Node> nodes;
    std::mt19937_64 rng;
    int cap = 300;
    bool evalAtCap = false, solver = false, decisive = false;
    double c = 1.0;
    explicit Mcts(uint64_t seed) : rng(seed) {}

    int playout(Pos p) {
        std::vector<Move> ms;
        for (int i = 0; i < cap; i++) {
            p.gen(ms);
            if (ms.empty()) return p.stm ^ 1;
            int mover = p.stm;
            if (p.play(ms[rng() % ms.size()])) return mover;
        }
        if (evalAtCap) {
            int v = material(p);
            return v > 0 ? p.stm : v < 0 ? p.stm ^ 1 : -1;
        }
        return -1;
    }

    // a fresh node for position p (side to move p.stm): its moves, and an immediate win if decisive
    void fill(Node& n, const Pos& p) {
        p.gen(n.untried);
        if (n.untried.empty()) { n.winner = n.mover; return; }  // side to move has no move: loses
        if (decisive)
            for (auto& m : n.untried) {
                Pos q = p;
                if (q.play(m)) { n.winner = p.stm; return; }
            }
    }

    // MCTS-Solver: after child `k` of `n` was proven, try to prove n
    void solve(int n) {
        Node& nd = nodes[n];
        if (nd.winner >= 0) return;
        int toMove = nd.mover ^ 1;
        bool allLost = nd.untried.empty();
        for (int k : nd.kids) {
            if (nodes[k].winner == toMove) { nd.winner = toMove; return; }
            if (nodes[k].winner != nd.mover) allLost = false;
        }
        if (allLost) nd.winner = nd.mover;
    }

    // deadline: optional wall-clock guard (seconds since `start`), checked every 64 iterations
    Move search(const Pos& root, int iterations, double deadline = 0) {
        auto start = std::chrono::steady_clock::now();
        nodes.clear();
        nodes.reserve(iterations + 1);
        nodes.push_back(Node{});
        nodes[0].parent = -1;
        nodes[0].mover = root.stm ^ 1;
        root.gen(nodes[0].untried);
        for (int it = 0; it < iterations; it++) {
            if (deadline > 0 && (it & 63) == 0 && it > 0 &&
                std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count() > deadline) break;
            if (solver && nodes[0].winner >= 0) break;
            Pos p = root;
            int n = 0;
            while (nodes[n].winner < 0 && nodes[n].untried.empty() && !nodes[n].kids.empty()) {
                double lnN = std::log((double)nodes[n].visits), bestU = -1e9;
                int bk = -1, toMove = nodes[n].mover ^ 1;
                for (int k : nodes[n].kids) {
                    const Node& ch = nodes[k];
                    double u;
                    if (solver && ch.winner >= 0) u = ch.winner == toMove ? 1e9 : -1e8;  // proven win / loss
                    else u = ch.wins / ch.visits + c * std::sqrt(lnN / ch.visits);
                    if (u > bestU) { bestU = u; bk = k; }
                }
                n = bk;
                p.play(nodes[n].m);
            }
            int winner;
            if (nodes[n].winner >= 0) winner = nodes[n].winner;
            else if (nodes[n].untried.empty()) winner = p.stm ^ 1;  // no legal move: side to move loses
            else {
                auto& un = nodes[n].untried;
                size_t i = rng() % un.size();
                Move m = un[i];
                un[i] = un.back();
                un.pop_back();
                Node ch;
                ch.m = m;
                ch.parent = n;
                ch.mover = p.stm;
                if (p.play(m)) ch.winner = ch.mover;
                else fill(ch, p);
                nodes.push_back(std::move(ch));
                int id = (int)nodes.size() - 1;
                nodes[n].kids.push_back(id);
                n = id;
                winner = nodes[n].winner >= 0 ? nodes[n].winner : playout(p);
            }
            bool proving = solver && nodes[n].winner >= 0;
            for (int k = n; k >= 0; k = nodes[k].parent) {
                nodes[k].visits++;
                nodes[k].wins += winner < 0 ? 0.5f : winner == nodes[k].mover ? 1.f : 0.f;
                if (proving && k != n) {
                    solve(k);
                    if (nodes[k].winner < 0) proving = false;
                }
            }
        }
        // a proven win if there is one; otherwise the most visited child that is not proven lost
        int toMove = root.stm, best = -1;
        for (int k : nodes[0].kids) {
            const Node& ch = nodes[k];
            if (ch.winner == toMove) return ch.m;
            bool lost = ch.winner >= 0 && ch.winner != toMove;
            if (best < 0) best = k;
            bool bestLost = nodes[best].winner >= 0 && nodes[best].winner != toMove;
            if ((bestLost && !lost) || (lost == bestLost && ch.visits > nodes[best].visits)) best = k;
        }
        return nodes[best].m;
    }
};

// Plain fixed-depth negamax alpha-beta on material, pushes searched first, no transposition table,
// random choice among equal root moves. Deterministic node count for a given position and depth.
struct AlphaBeta {
    std::mt19937_64 rng;
    long long nodes = 0;
    std::vector<Move> mv[16];
    explicit AlphaBeta(uint64_t seed) : rng(seed) {}
    static const int WIN = 1000000;

    void order(const Pos& p, std::vector<Move>& ms) {
        uint64_t op = p.s[p.stm ^ 1];
        size_t front = 0;
        for (size_t i = 0; i < ms.size(); i++) {
            const Move& m = ms[i];
            bool push = false;
            for (int j = 1; j <= m.k; j++) if (op >> T.nb[m.a][m.d][j] & 1) { push = true; break; }
            if (push) std::swap(ms[i], ms[front++]);
        }
    }
    std::chrono::steady_clock::time_point start;
    double deadline = 0;
    bool aborted = false;
    int quiesce = 0;  // > 0: at the horizon, keep searching moves that push a stone off (at most this many plies)
    uint64_t nextClock = 0;
    // threshold, not nodes % 1024: quiescence nodes advance the counter too, so a modulo can be skipped forever
    bool outOfTime() {
        if (deadline > 0 && nodes >= nextClock) {
            nextClock = nodes + 512;
            if (std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count() > deadline) aborted = true;
        }
        return aborted;
    }
    int qs(const Pos& p, int alpha, int beta, int ply, int left) {
        nodes++;
        if (outOfTime()) return 0;
        int stand = material(p);
        if (stand >= beta || left == 0 || ply >= 15) return stand;
        if (stand > alpha) alpha = stand;
        auto& ms = mv[ply];
        genPushOffs(p, ms);
        int best = stand;
        for (size_t i = 0; i < ms.size(); i++) {
            Pos q = p;
            int s = q.play(ms[i]) ? WIN - ply - 1 : -qs(q, -beta, -alpha, ply + 1, left - 1);
            if (aborted) return 0;
            if (s > best) best = s;
            if (s > alpha) alpha = s;
            if (alpha >= beta) break;
        }
        return best;
    }
    int ab(const Pos& p, int depth, int alpha, int beta, int ply) {
        nodes++;
        if (outOfTime()) return 0;
        if (depth == 0) return quiesce > 0 ? qs(p, alpha, beta, ply, quiesce) : material(p);
        auto& ms = mv[ply];
        p.gen(ms);
        if (ms.empty()) return -WIN + ply;
        order(p, ms);
        int best = -2 * WIN;
        for (size_t i = 0; i < ms.size(); i++) {
            Pos q = p;
            int s = q.play(ms[i]) ? WIN - ply - 1 : -ab(q, depth - 1, -beta, -alpha, ply + 1);
            if (s > best) best = s;
            if (s > alpha) alpha = s;
            if (alpha >= beta) break;
        }
        return best;
    }
    Move rootSearch(const Pos& p, const std::vector<Move>& root, int depth) {
        int alpha = -2 * WIN;
        Move bm = root[0];
        for (auto& m : root) {
            Pos q = p;
            // window alpha-1 keeps exact ties at the root; only a strictly better move replaces bm,
            // so among equal moves the first after the shuffle (a random one) is kept
            int s = q.play(m) ? WIN - 1 : -ab(q, depth - 1, -2 * WIN, -(alpha - 1), 1);
            if (aborted) break;
            if (s > alpha) { alpha = s; bm = m; }
        }
        return bm;
    }
    // deadline = 0: exactly `depth` (the lab). deadline > 0 (the shipped boss): depths 1..depth, and
    // the last COMPLETED depth's move if the clock runs out -- so a slow judge weakens it, never times out.
    Move search(const Pos& p, int depth, double deadlineSec = 0) {
        nodes = 0;
        aborted = false;
        deadline = deadlineSec;
        nextClock = 512;
        start = std::chrono::steady_clock::now();
        std::vector<Move> root;
        p.gen(root);
        std::shuffle(root.begin(), root.end(), rng);
        order(p, root);
        if (deadline <= 0) return rootSearch(p, root, depth);
        Move bm = root[0];
        for (int d = 1; d <= depth; d++) {
            Move m = rootSearch(p, root, d);
            if (aborted) break;
            bm = m;
        }
        return bm;
    }
};

}  // namespace shobu
// The lab's main searcher: iterative-deepening negamax alpha-beta with a transposition table,
// killer moves, push-off quiescence (useQ) and an optional node budget. Shared by lab.cpp and the
// Wood 2 boss (tools/bundle_boss.py "engine"), so the lab measures what ships.

#include <algorithm>
#include <chrono>
#include <random>
#include <vector>

namespace shobu {

static const int WIN = 1000000;
static const int W[5] = {0, 0, 100, 150, 180};

struct Zob {
    uint64_t z[2][64], side;
    Zob() {
        std::mt19937_64 r(12345);
        for (auto& a : z) for (auto& b : a) b = r();
        side = r();
    }
};
static const Zob Z;
static uint64_t hashOf(const Pos& p) {
    uint64_t h = p.stm ? Z.side : 0;
    for (int c = 0; c < 2; c++) {
        uint64_t b = p.s[c];
        while (b) { h ^= Z.z[c][__builtin_ctzll(b)]; b &= b - 1; }
    }
    return h;
}

static int evalSide(const Pos& p) {
    int v = 0;
    for (int b = 0; b < 4; b++) {
        v += W[__builtin_popcountll((p.s[p.stm] >> (16 * b)) & 0xFFFF)];
        v -= W[__builtin_popcountll((p.s[p.stm ^ 1] >> (16 * b)) & 0xFFFF)];
    }
    return v;
}

struct TTE { uint64_t key; int16_t depth; int8_t flag; int score; Move best; };

struct Searcher {
    std::vector<TTE> tt;
    uint64_t mask, nodes = 0, nodeLimit = 0;
    bool stop = false;
    double deadline = 0;  // seconds; 0 = none (the lab). The shipped boss uses a guard: a slow judge weakens it, never times out
    std::chrono::steady_clock::time_point startTime;
    uint64_t nextClock = 0;
    std::vector<Move> mv[64];
    std::mt19937_64 rng;
    int noise = 0;
    uint64_t salt = 0;
    bool useQ = false;
    int ev(const Pos& p) {
        int v = evalSide(p);
        if (noise) v += int((hashOf(p) ^ salt) * 0x9E3779B97F4A7C15ull >> 40) % (2 * noise + 1) - noise;
        return v;
    }
    // quiescence: only moves that push a stone off a board
    int qs(const Pos& p, int alpha, int beta, int ply, int left) {
        nodes++;
        int stand = ev(p);
        if (stand >= beta || left == 0) return stand;
        if (stand > alpha) alpha = stand;
        std::vector<Move>& ms = mv[ply];
        p.gen(ms);
        if (ms.empty()) return -WIN + ply;
        uint64_t op = p.s[p.stm ^ 1];
        int best = stand;
        std::vector<Move> caps;
        for (auto& m : ms) {
            if (T.nb[m.a][m.d][m.k + 1] >= 0) continue;
            for (int j = 1; j <= m.k; j++)
                if (op >> T.nb[m.a][m.d][j] & 1) { caps.push_back(m); break; }
        }
        for (auto& m : caps) {
            Pos q = p;
            int s = q.play(m) ? WIN - ply - 1 : -qs(q, -beta, -alpha, ply + 1, left - 1);
            if (s > best) best = s;
            if (s > alpha) alpha = s;
            if (alpha >= beta) break;
        }
        return best;
    }
    Move killer[64];
    std::vector<std::pair<int, Move>> scoreBuf;
    // TT move, then pushes that remove a stone, then other pushes, then the killer, then the rest
    void orderMoves(const Pos& p, std::vector<Move>& ms, Move ttm, int ply) {
        auto& sc = scoreBuf;  // not thread_local: MinGW crashes destroying it at thread exit
        sc.clear();
        uint64_t op = p.s[p.stm ^ 1];
        for (auto& m : ms) {
            int v = 0;
            if (sameMove(m, ttm)) v = 1000;
            else {
                for (int j = 1; j <= m.k; j++) {
                    int c = T.nb[m.a][m.d][j];
                    if (op >> c & 1) { v = T.nb[m.a][m.d][m.k + 1] < 0 ? 500 : 100; break; }
                }
                if (!v && sameMove(m, killer[ply])) v = 50;
            }
            sc.push_back({v, m});
        }
        std::stable_sort(sc.begin(), sc.end(), [](auto& a, auto& b) { return a.first > b.first; });
        for (size_t i = 0; i < ms.size(); i++) ms[i] = sc[i].second;
    }
    Searcher(int log2 = 20, uint64_t seed = 1) : tt(1ull << log2), mask((1ull << log2) - 1), rng(seed) {}
    void clear() { std::fill(tt.begin(), tt.end(), TTE{0, -1, 0, 0, {}}); for (auto& k : killer) k = Move{255, 0, 0, 0}; }

    int ab(const Pos& p, int depth, int alpha, int beta, int ply) {
        nodes++;
        if (nodeLimit && nodes >= nodeLimit) { stop = true; return 0; }
        // threshold, not nodes % 1024: quiescence nodes advance the counter too, so a modulo can be skipped forever
        if (deadline > 0 && nodes >= nextClock) {
            nextClock = nodes + 1024;
            if (std::chrono::duration<double>(std::chrono::steady_clock::now() - startTime).count() > deadline) { stop = true; return 0; }
        }
        if (depth == 0) return useQ ? qs(p, alpha, beta, ply, 6) : ev(p);
        uint64_t h = hashOf(p);
        TTE& e = tt[h & mask];
        Move ttm{255, 0, 0, 0};
        if (e.key == h) {
            ttm = e.best;
            if (e.depth >= depth) {
                int s = e.score;
                if (s > WIN - 1000) s -= ply; else if (s < -WIN + 1000) s += ply;
                if (e.flag == 0 || (e.flag == 1 && s >= beta) || (e.flag == 2 && s <= alpha)) return s;
            }
        }
        std::vector<Move>& ms = mv[ply];
        p.gen(ms);
        if (ms.empty()) return -WIN + ply;
        // order: TT move first, then moves that push (capture-ish), rest
        orderMoves(p, ms, ttm, ply);
        int a0 = alpha, best = -WIN * 2;
        Move bm = ms[0];
        for (size_t i = 0; i < ms.size(); i++) {
            Pos q = p;
            int s;
            if (q.play(ms[i])) s = WIN - ply - 1;
            else s = -ab(q, depth - 1, -beta, -alpha, ply + 1);
            if (stop) return 0;
            if (s > best) { best = s; bm = ms[i]; }
            if (s > alpha) alpha = s;
            if (alpha >= beta) {
                if (!sameMove(ms[i], killer[ply])) killer[ply] = ms[i];
                break;
            }
        }
        int st = best;
        if (st > WIN - 1000) st += ply; else if (st < -WIN + 1000) st -= ply;
        e = TTE{h, int16_t(depth), int8_t(best <= a0 ? 2 : best >= beta ? 1 : 0), st, bm};
        return best;
    }

    // root: returns best move; fixed depth or node budget (iterative deepening)
    Move pick(const Pos& p, int depth, uint64_t budget, int* outScore = nullptr, int* outDepth = nullptr) {
        std::vector<Move> root;
        p.gen(root);
        Move best = root[0];
        int bestScore = 0, reached = 0;
        nodes = 0; stop = false; nodeLimit = budget;
        startTime = std::chrono::steady_clock::now();
        nextClock = 1024;
        int maxD = depth ? depth : 48;  // mv[64]: leave room for quiescence plies
        for (int d = 1; d <= maxD; d++) {
            // shuffle equal-ish moves: root ordering with previous best first
            std::shuffle(root.begin(), root.end(), rng);
            for (size_t i = 0; i < root.size(); i++) if (sameMove(root[i], best)) { std::swap(root[0], root[i]); break; }
            int alpha = -WIN * 2, iterBest = -WIN * 2;
            Move ib = root[0];
            for (auto& m : root) {
                Pos q = p;
                int s = q.play(m) ? WIN - 1 : -ab(q, d - 1, -WIN * 2, -alpha, 1);
                if (stop) break;
                if (s > iterBest) { iterBest = s; ib = m; }
                if (s > alpha) alpha = s;
            }
            if (stop) break;
            best = ib; bestScore = iterBest; reached = d;
            if (iterBest > WIN - 1000) break;
        }
        if (outScore) *outScore = bestScore;
        if (outDepth) *outDepth = reached;
        return best;
    }
};

}  // namespace shobu
// Standalone boss: reads the referee protocol (config/stub.txt), plays BOSS_MOVE.
// Seeded from the clock: a fixed seed would replay one game forever, and a player could memorise it.
// Bundled with shobu.hpp + bosses.hpp by tools/bundle_boss.py.

#include <chrono>
#include <iostream>
#include <string>

using namespace shobu;

// wire (x, y): x left to right, y top to bottom, black home at the bottom
static int cellOf(int x, int y) {
    int b = (y >= 4 ? 0 : 2) + (x >= 4 ? 1 : 0);
    return 16 * b + 4 * (3 - y % 4) + x % 4;
}
static std::string wireOf(const Move& m) {
    auto xy = [](int i, int& x, int& y) {
        int b = i >> 4, r = (i >> 2) & 3, c = i & 3;
        x = 4 * (b & 1) + c;
        y = 4 * (b < 2 ? 1 : 0) + (3 - r);
    };
    int px, py, ax, ay;
    xy(m.p, px, py); xy(m.a, ax, ay);
    return std::to_string(px) + " " + std::to_string(py) + " " + std::to_string(ax) + " " + std::to_string(ay) + " " +
           std::to_string(DC[m.d] * m.k) + " " + std::to_string(-DR[m.d] * m.k);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::mt19937_64 rng(BOSS_SEED);
    int round, myColor;
    while (std::cin >> round >> myColor) {
        auto t0 = std::chrono::steady_clock::now();
        Pos p;
        p.s[0] = p.s[1] = 0;
        p.stm = myColor;
        for (int y = 0; y < 8; y++) {
            std::string row;
            std::cin >> row;
            for (int x = 0; x < 8; x++) {
                if (row[x] == 'b') p.s[0] |= 1ull << cellOf(x, y);
                else if (row[x] == 'w') p.s[1] |= 1ull << cellOf(x, y);
            }
        }
        std::string last;
        std::getline(std::cin >> std::ws, last);
        int n;
        std::cin >> n;
        std::cin.ignore();
        std::vector<std::string> legal(n);
        for (auto& l : legal) std::getline(std::cin, l);
        Move m = BOSS_MOVE(p, rng);
        std::string w = wireOf(m);
        bool ok = false;
        for (auto& l : legal) if (l == w) ok = true;
        double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
        std::cerr << "boss " << BOSS_NAME << " " << ms << " ms" << (ok ? "" : " ILLEGAL, fallback") << std::endl;
        std::cout << (ok ? w : legal[0]) << std::endl;
    }
}
